function settings(){open(`<div class="eyebrow">YOUR PACE</div><h2>Make room for a little music.</h2><p class="modal-sub">Choose a daily intention. Your lessons stay available even when life gets busy.</p><label for="goal">Daily practice goal</label><select id="goal">${[5,10,15,20,30].map(n=>`<option value="${n}" ${state.goal===n?'selected':''}>${n} minutes</option>`).join('')}</select><div class="modal-actions"><button class="primary" id="saveGoal">Save my intention →</button></div><p class="fine">Progress is saved only in this browser. There is no account sync in this first version. You can export your records from My progress.</p>`);$('#saveGoal').onclick=()=>{state.goal=+$('#goal').value;save();render();close();toast('Your practice intention is saved.');};}$('#goalBtn').onclick=settings;$('#settings').onclick=settings;$('.brand').onclick=e=>{e.preventDefault();go('home');};document.addEventListener('click',e=>{if(e.target.id==='tryViolin'){close();go('path');}});render();
